export function shuffleBag(ids,current,random=Math.random){const a=ids.filter(x=>x!==current);for(let i=a.length-1;i>0;i--){const j=Math.floor(random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
// Visit each unseen quote before refilling. Prefer variety without starving items.
export function chooseNext(quotes,remaining,current,random=Math.random){if(!remaining.length)remaining.push(...quotes.filter(q=>q.id!==current.id).map(q=>q.id));let best=-Infinity,candidates=[];for(const id of remaining){const q=quotes.find(x=>x.id===id);if(!q)continue;const score=(q.image_group!==current.image_group?4:0)+(q.mood!==current.mood?2:0)+(q.topic!==current.topic?1:0);if(score>best){best=score;candidates=[q];}else if(score===best)candidates.push(q);}const q=candidates[Math.floor(random()*candidates.length)]||current;const i=remaining.indexOf(q.id);if(i>=0)remaining.splice(i,1);return q;}
export function validate(data){if(!data||!Array.isArray(data.quotes)||!data.quotes.length)throw Error('Thư viện chưa có câu nào.');const ids=new Set();for(const q of data.quotes){for(const k of ['id','hanzi','pinyin','vietnamese','image','theme','audio','download'])if(typeof q[k]!=='string'||!q[k].trim())throw Error('Thiếu dữ liệu câu.');if(!/^tc-\d{3}$/.test(q.id)||ids.has(q.id))throw Error('Trùng hoặc sai mã câu.');ids.add(q.id);for(const [key,pattern]of[['image',/^assets\/[a-z0-9-]+\.(jpg|webp|png)$/],['audio',/^audio\/[a-z0-9-]+\.mp3$/],['download',/^downloads\/[a-z0-9-]+\.jpg$/]])if(!pattern.test(q[key]))throw Error('Đường dẫn không hợp lệ.');if(!q.download_allowed)throw Error('Chưa có quyền tải artwork.');}return data.quotes;}
